/*
 * inference(x[N_FEATURES]):
 *   1. x_s[i] = (x[i] - SCALER_MEAN[i]) / SCALER_SCALE[i]
 *   2. For j in [0, N_COMPONENTS):
 *        diff = sum((x_s[i] - NYS_COMPONENTS[j*N_FEATURES+i])^2)
 *        k[j] = exp(-GAMMA * diff)
 *   3. For j in [0, N_COMPONENTS):
 *        z[j] = sum(NYS_NORMALIZATION[j*N_COMPONENTS+m] * k[m])
 *   4. score = sum(SVM_W[j] * z[j]) + INTERCEPT
 *   5. if score < THRESHOLD_1 -> immediate alert
 *      if score < THRESHOLD_2 for 3 frames -> sustained alert
 */
